/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    METSalesOrderShipmentLoadHeader shipmentLoadHeader;
    METSalesOrderShipmentLoadLines  shipmentLoadLines;
    CompanyInfo CompanyInfo;    


    while select CompanyInfo
        where CompanyInfo.DataArea != 'DAT'
    {
        changecompany (CompanyInfo.DataArea)
        {
            while select ShipmentId from shipmentLoadHeader
                order by ShipmentId
                where shipmentLoadHeader.DataAreaId == CompanyInfo.DataArea
            {
                ttsbegin;

                while select forupdate shipmentLoadLines where shipmentLoadLines.ShipmentId == shipmentLoadHeader.ShipmentId
                {
                    if (shipmentLoadLines.displayPickListStatus() == WMSExpeditionStatus::Complete ||
                        shipmentLoadLines.displayPickListStatus() == WMSExpeditionStatus::Cancelled)
                    {
                        shipmentLoadLines.PickingListComplete = NoYes::Yes;
                        shipmentLoadLines.update();
                    }
                    else
                    {
                        shipmentLoadLines.PickingListComplete = NoYes::No;
                        shipmentLoadLines.update();
                    }
                }
                ttscommit;

                METSalesOrderShipmentLoadHeader::updatePickComplete(shipmentLoadHeader.ShipmentId);
            }

            info('Completed for company: ' + CompanyInfo.DataArea);
        }
    }


    info('Done');
}
